content.content:
const frontmostApp = () => {
  try {
    return osa('tell application "System Events" to name of first process whose frontmost is true');
  } catch {
    return "";
  }
};

// CDP input and screenshots work on a hidden window, so a run never needs Obsidian on screen.
const hideObsidian = () => {
  try {
    osa('tell application "System Events" to set visible of process "Obsidian" to false');
  } catch {}
};

const until = async (check, { timeout, label }) => {
  const deadline = Date.now() + timeout;
  while (!(await check())) {
    if (Date.now() > deadline) throw new Error(`timeout: ${label}`);
    await new Promise((r) => setTimeout(r, 200));
  }
};

// Quit and relaunch are separate process calls; the auto-mode classifier blocks them combined.
const quitObsidian = async () => {
  run("osascript", ["-e", 'quit app "Obsidian"']);
  await until(() => obsidianPids().length === 0, { timeout: 20000, label: "Obsidian exit" });
};

const launchWithPort = async (port) => {
  // -g keeps Obsidian in the background; the driver uses focus emulation, not a frontmost window.
  run("open", ["-g", "-na", OBSIDIAN_APP, "--args", `--remote-debugging-port=${port}`]);
  await until(() => probePort(port), { timeout: 30000, label: `CDP port ${port}` });
};

export const launch = async ({ worktree, slot, port = DEFAULT_PORT, hide = true }) => {
  const started = Date.now();
  const wasFrontmost = frontmostApp() === "Obsidian";
  const report = await doctor({ worktree, slot, port });
  if (!report.ok) throw Object.assign(new Error(report.error), { exitCode: 2 });
  const { vault, branch, obsidian } = report;

  let action = "attach";
  let raised = false;
  if (obsidian.state === "running-without-port") {
    action = "relaunch";
    await quitObsidian();
    await launchWithPort(port);
    raised = true;
  } else if (obsidian.state === "not-running") {
    action = "launch";
    await launchWithPort(port);
    raised = true;
  }

  // The obsidian:// URL raises the window, so only send it when the vault is not already open.
  let client = await findVaultTarget({ port, root: vault.root }).catch(() => null);
  if (client) {
    await client.activate();
  } else {
    run("open", ["-g", `obsidian://open?path=${encodeURIComponent(vault.root)}`]);
    client = await connect({ port, root: vault.root, timeout: 45000 });
    raised = true;
  }
  // Launching, the obsidian:// handler and some plugin reloads each raise the window; keep it down
  // for the whole run unless Trang was using Obsidian when we started.
  const keepHidden = hide && !wasFrontmost;
  if (raised && keepHidden) hideObsidian();
  const hideTimer = keepHidden ? setInterval(hideObsidian, 1500) : null;
  if (hideTimer) hideTimer.unref?.();
  const stopHiding = () => hideTimer && clearInterval(hideTimer);
  acquireLock({ lockFile: vault.lockFile, branch });
  return { client, vault, branch, action, obsidianBefore: obsidian.state, stopHiding, ms: Date.now() - started };
};

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = parseArgs(process.argv.slice(2));
  try {
    const { client, vault, action, ms, stopHiding } = await launch({
      worktree: args.worktree ?? resolveWorktree(),
      slot: args.slot,
      port: Number(args.port ?? DEFAULT_PORT),
      hide: !args["no-hide"],
    });
