import { App } from "obsidian";
import { useEffect, useMemo, useRef, useState, type ReactElement } from "react";
import { SearchDropdown } from "~/components/SearchDropdown";
import { DiscourseNode } from "~/types";
import { getAllDiscourseNodeColors } from "~/utils/colorUtils";
import {
  NODE_TYPE_FILTER_SEARCH_THRESHOLD,
  filterNodeTypesByQuery,
  fromPanelSelectedIds,
  hasActiveTypeFilter,
  toPanelSelectedIds,
} from "~/utils/discourseNodeTypeFilter";

const NodeTypeFilterRow = ({
  color,
  isChecked,
  nodeType,
  onSelectOnly,
  onToggle,
}: {
  color: string | undefined;
  isChecked: boolean;
  nodeType: DiscourseNode;
  onSelectOnly: () => void;
  onToggle: () => void;
}): ReactElement => (
  <div className="hover:bg-modifier-hover group flex items-center gap-2 px-3 py-1.5">
    <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-2">
      <input
        type="checkbox"
        checked={isChecked}
        onChange={onToggle}
        className="shrink-0"
      />
      {color && (
        <span
          style={{ backgroundColor: color }}
          className="h-3 w-3 shrink-0 rounded-full"
        />
      )}
      <span className="text-normal truncate text-sm">{nodeType.name}</span>
    </label>
    <button
      type="button"
      // Pointer-only: arrow keys stop once per row, on the checkbox.
      tabIndex={-1}
      // Hidden until the row is hovered so the list stays scannable.
      className="text-muted hover:text-normal shrink-0 opacity-0 transition-opacity group-hover:opacity-100"
      onClick={(event) => {
        event.stopPropagation();
        onSelectOnly();
      }}
      onMouseDown={(event) => event.preventDefault()}
    >
      Only
    </button>
  </div>
);

export const NodeTypeFilterPanel = ({
  isInline = false,
  nodeTypes,
  onSelectOnly,
  onSelectedNodeTypeIdsChange,
  selectedNodeTypeIds,
}: {
  isInline?: boolean;
  nodeTypes: DiscourseNode[];
  onSelectOnly?: () => void;
  onSelectedNodeTypeIdsChange: (ids: string[]) => void;
  selectedNodeTypeIds: string[];
}): ReactElement => {
  const [query, setQuery] = useState("");
  const searchRef = useRef<HTMLInputElement | null>(null);

  const allTypeIds = useMemo(
    () => nodeTypes.map((nodeType) => nodeType.id),
    [nodeTypes],
  );
  const isFilterActive = hasActiveTypeFilter({
    selectedTypeIds: selectedNodeTypeIds,
    allTypeIds,
  });
  const selectedIds = useMemo(
    () =>
      toPanelSelectedIds({ selectedTypeIds: selectedNodeTypeIds, allTypeIds }),
    [allTypeIds, selectedNodeTypeIds],
  );
  const onSelectedIdsChange = (panelIds: string[]): void =>
    onSelectedNodeTypeIdsChange(
      fromPanelSelectedIds({ panelSelectedIds: panelIds, allTypeIds }),
    );

  // Inline hosts keep focus in the editor, and the search box needs focus.
  const showTypeSearch =
    !isInline && nodeTypes.length > NODE_TYPE_FILTER_SEARCH_THRESHOLD;

  const colorsById = useMemo(() => {
    const byId = new Map<string, string>();
    getAllDiscourseNodeColors(nodeTypes).forEach(({ nodeType, colors }) => {
      byId.set(nodeType.id, colors.backgroundColor);
    });
    return byId;
  }, [nodeTypes]);

  const filteredNodeTypes = useMemo(
    () => filterNodeTypesByQuery(nodeTypes, query),
    [nodeTypes, query],
  );

  const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);

  useEffect(() => {
    if (showTypeSearch) searchRef.current?.focus();
  }, [showTypeSearch]);

  const toggleType = (id: string): void => {
    onSelectedIdsChange(
      selectedIdSet.has(id)
        ? selectedIds.filter((selectedId) => selectedId !== id)
        : [...selectedIds, id],
    );
  };

  return (
    <>
      {/* Clearing is the only thing this control ever does, so it says so and
          appears only when there is a filter to clear. A "select all" checkbox
          would sit checked-and-inert whenever no filter is active, since an empty
          selection and a full one are the same state. */}
      {isFilterActive && (
        <div className="border-modifier-border border-b p-2">
          <button
            type="button"
            onClick={(event) => {
              // This button unmounts on clear; if it held focus, park focus on the dropdown panel so arrow keys keep working.
              if (activeDocument.activeElement === event.currentTarget) {
                event.currentTarget
                  .closest<HTMLElement>("[data-search-dropdown-panel]")
                  ?.focus();
              }
              onSelectedIdsChange([]);
            }}
            onMouseDown={(event) => event.preventDefault()}
            className="w-full text-sm"
          >
            {`Clear filter (${selectedIds.length})`}
          </button>
        </div>
      )}
      {showTypeSearch && (
        <div className="border-modifier-border border-b p-2">
          <input
            ref={searchRef}
            type="text"
            value={query}
            placeholder="Filter types…"
            onChange={(event) => setQuery(event.target.value)}
            className="w-full"
          />
        </div>
      )}
      <div
        className={
          // Shorter inline, so the host's results keep room below the panel.
          isInline
            ? "max-h-40 overflow-y-auto py-1"
            : "max-h-64 overflow-y-auto py-1"
        }
      >
        {filteredNodeTypes.length === 0 ? (
          <div className="text-muted p-4 text-center text-sm">
            No matching node types
          </div>
        ) : (
          filteredNodeTypes.map((nodeType) => (
            <NodeTypeFilterRow
              key={nodeType.id}
              color={colorsById.get(nodeType.id)}
              isChecked={selectedIdSet.has(nodeType.id)}
              nodeType={nodeType}
              onSelectOnly={() => {
                onSelectedIdsChange([nodeType.id]);
                onSelectOnly?.();
              }}
              onToggle={() => toggleType(nodeType.id)}
            />
          ))
        )}
      </div>
    </>
  );
};

export const NodeTypeFilterMenu = ({
  app,
  isOpen,
  nodeTypes,
  onOpenChange,
  onSelectedNodeTypeIdsChange,
  selectedNodeTypeIds,
}: {
  app: App;
  isOpen: boolean;
  nodeTypes: DiscourseNode[];
  onOpenChange: (isOpen: boolean) => void;
  onSelectedNodeTypeIdsChange: (ids: string[]) => void;
  selectedNodeTypeIds: string[];
}): ReactElement => {
  const allTypeIds = useMemo(
    () => nodeTypes.map((nodeType) => nodeType.id),
    [nodeTypes],
  );

  const isFilterActive = hasActiveTypeFilter({
    selectedTypeIds: selectedNodeTypeIds,
    allTypeIds,
  });

  const activeFilterCount = isFilterActive ? selectedNodeTypeIds.length : 0;

  return (
    <SearchDropdown
      app={app}
      ariaLabel={
        activeFilterCount > 0
          ? `Filter by type, ${activeFilterCount} selected`
          : "Filter by type"
      }
      badgeCount={activeFilterCount}
      iconName="filter"
      isActive={isFilterActive}
      isDisabled={nodeTypes.length === 0}
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      panelClassName="w-64"
      title={
        nodeTypes.length === 0
          ? "No discourse node types configured"
          : "Filter by type"
      }
    >
      <NodeTypeFilterPanel
        nodeTypes={nodeTypes}
        onSelectedNodeTypeIdsChange={onSelectedNodeTypeIdsChange}
        selectedNodeTypeIds={selectedNodeTypeIds}
      />
    </SearchDropdown>
  );
};

// ENG-2478 regression: advanced search's type filter dropdown must be unchanged by the split.
import { mkdirSync, writeFileSync } from "node:fs";
const MODAL = ".dg-node-search-modal";
// SNAPSHOT_DIR=<dir> dumps each scenario's full panel snapshot so before/after runs can be diffed.
const dump = (name, snap) => {
  const dir = process.env.SNAPSHOT_DIR;
  if (!dir) return snap;
  mkdirSync(dir, { recursive: true });
  writeFileSync(`${dir}/${name}.json`, JSON.stringify(snap, null, 2));
  return snap;
};
const BUTTON = `${MODAL} button[aria-label^="Filter by type"]`;
const PANEL = `${MODAL} [data-search-dropdown-panel]`;

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(BUTTON)})`, { label: "filter button rendered" });
};

const openFilter = async ({ client, json }) => {
  await client.evaluate(`document.querySelector(${json(BUTTON)}).click(); return true;`);
  await client.waitFor(`!!document.querySelector(${json(PANEL)})`, { label: "panel open" });
};

const snapshot = ({ client, json }) =>
  client.evaluate(`const panel = document.querySelector(${json(PANEL)});
    const button = document.querySelector(${json(BUTTON)});
    return {
      panelOpen: !!panel,
      buttonLabel: button?.getAttribute("aria-label"),
      buttonClass: button?.className,
      clearLabel: panel?.querySelector("button:not([tabindex='-1'])")?.textContent?.trim() ?? null,
      hasTypeSearch: !!panel?.querySelector("input[type=text]"),
      rows: Array.from(panel?.querySelectorAll("input[type=checkbox]") ?? []).map((c) => ({
        name: c.closest("label")?.textContent?.trim(), checked: c.checked })),
      // Normalised markup so before/after runs diff exactly.
      html: panel?.innerHTML.replace(/\\s+/g, " "),
    };`);

export default [
  {
    name: "advanced search filter: initial",
    input: "open node search; click Filter by type",
    expected: "panel open, every row checked, no Clear filter button",
    run: async (ctx) => {
      await openSearch(ctx);
      await openFilter(ctx);
      return dump("initial", await snapshot(ctx));
    },
    expect: (a) => ({
      pass: a.panelOpen && a.rows.length > 0 && a.rows.every((r) => r.checked) && a.clearLabel === null,
      actual: `${a.rows.length} rows, all checked=${a.rows.every((r) => r.checked)}, clear=${a.clearLabel}`,
    }),
  },
  {
    name: "advanced search filter: Only",
    input: "open filter; click Only on the first row",
    expected: "panel stays open, one row checked, Clear filter (1), badge on button",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await openFilter(ctx);
      await client.evaluate(`document.querySelector(${json(`${PANEL} button[tabindex='-1']`)}).click(); return true;`);
      await client.waitFor(`!!Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter shown" });
      return dump("only", await snapshot(ctx));
    },
    expect: (a) => ({
      pass: a.panelOpen && a.rows.filter((r) => r.checked).length === 1 && a.clearLabel === "Clear filter (1)" && /1 selected/.test(a.buttonLabel),
      actual: `open=${a.panelOpen}, checked=${a.rows.filter((r) => r.checked).length}, clear=${a.clearLabel}, label=${a.buttonLabel}`,
    }),
  },
  {
    name: "advanced search filter: Clear filter",
    input: "Only on first row, then Clear filter",
    expected: "every row checked again, Clear filter gone, plain button label",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await openFilter(ctx);
      await client.evaluate(`document.querySelector(${json(`${PANEL} button[tabindex='-1']`)}).click(); return true;`);
      await client.waitFor(`!!Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter shown" });
      await client.evaluate(`Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter")).click(); return true;`);
      await client.waitFor(`!Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter gone" });
      return dump("clear", await snapshot(ctx));
    },
    expect: (a) => ({
      pass: a.rows.every((r) => r.checked) && a.clearLabel === null && a.buttonLabel === "Filter by type",
      actual: `all checked=${a.rows.every((r) => r.checked)}, clear=${a.clearLabel}, label=${a.buttonLabel}`,
    }),
  },
];

