// ENG-2494 docs screenshots: summoning menu results, and the type filter open.
import { writeFileSync } from "node:fs";
const OUT = "/Users/trang.doan/Desktop/code/discourse-graph/.claude/worktrees/eng-2494-document-the-obsidian-node-summoning-menu-and-its/apps/website/public/docs/obsidian";
const MENU = ".dg-node-summon-menu";
const BUTTON = `${MENU} button[aria-label="Filter by type"]`;
const NOTE = "Summoning menu.md";
const PROSE = "Rest seems to help learning, see ";

const clickAt = async ({ client }, expr, label) => {
  const r = await client.evaluate(`const el = ${expr}; if (!el) return null;
    const b = el.getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 };`);
  if (!r) throw new Error(`no element: ${label}`);
  for (const type of ["mouseMoved", "mousePressed", "mouseReleased"])
    await client.send("Input.dispatchMouseEvent", { type, x: r.x, y: r.y, button: "left", clickCount: 1 });
};

const settle = (ctx, ms = 300) => ctx.client.evaluate(`return new Promise((r) => setTimeout(() => r(true), ${ms}));`);

// Crops to the typed line plus the menu, with some padding.
const shoot = async (ctx, file) => {
  const { client, json } = ctx;
  await client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 2, y: 2 });
  await settle(ctx);
  const clip = await client.evaluate(`const m = document.querySelector(${json(MENU)}).getBoundingClientRect();
    const line = app.workspace.activeLeaf.view.contentEl.querySelector(".cm-active.cm-line").getBoundingClientRect();
    const pad = 24;
    const x = Math.max(0, Math.min(m.left, line.left) - pad);
    const y = Math.max(0, Math.min(m.top, line.top) - pad);
    const right = Math.max(m.right, line.left + 520) + pad;
    const bottom = Math.max(m.bottom, line.bottom) + pad;
    return { x, y, width: right - x, height: bottom - y, scale: 2 };`);
  const { data } = await client.send("Page.captureScreenshot", { format: "png", clip });
  writeFileSync(`${OUT}/${file}`, Buffer.from(data, "base64"));
  return clip;
};

const openMenu = async (ctx, query) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(NOTE, `${PROSE}\n`);
  const trigger = await client.evaluate(`return app.plugins.plugins[${json(ctx.vault.pluginId)}].settings.nodeSearchTrigger;`);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    leaf.view.editor.focus();
    leaf.view.editor.setCursor({ line: 0, ch: ${PROSE.length} });
    return true;
  })();`);
  await client.typeText(trigger + query);
  await client.waitFor(`!!document.querySelector(${json(BUTTON)})`, { label: "summon menu open" });
  await settle(ctx);
};

const groups = (ctx) =>
  ctx.client.evaluate(`return Array.from(document.querySelectorAll(${ctx.json(`${MENU} .suggestion > :not(.suggestion-item)`)})).map((el) => el.textContent.trim());`);

export default [
  {
    name: "docs: menu results",
    input: 'type "@sleep" after prose',
    expected: "menu open with two or more type groups",
    run: async (ctx) => {
      await openMenu(ctx, "sleep");
      const g = await groups(ctx);
      await shoot(ctx, "node-summoning-menu.png");
      return g;
    },
    expect: (g) => ({ pass: g.length >= 2, actual: g.join(", ") }),
  },
  {
    name: "docs: type filter open",
    input: 'type "@sleep"; open filter; uncheck the first group\'s type',
    expected: "panel open above results, one type unchecked, Clear filter shown",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openMenu(ctx, "sleep");
      const [first] = await groups(ctx);
      await clickAt(ctx, `document.querySelector(${json(BUTTON)})`, "filter button");
      await client.waitFor(`!!document.querySelector(${json(`${MENU} input[type=checkbox]`)})`, { label: "panel open" });
      await clickAt(ctx, `Array.from(document.querySelectorAll(${json(`${MENU} label`)})).find((l) => l.textContent.trim().toLowerCase() === ${json(first.toLowerCase())})?.querySelector("input")`, `uncheck ${first}`);
      await client.waitFor(`!!Array.from(document.querySelectorAll(${json(`${MENU} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter shown" });
      const after = await groups(ctx);
      await shoot(ctx, "node-summoning-menu-type-filter.png");
      return { first, after };
    },
    expect: (a) => ({ pass: !a.after.some((g) => g.toLowerCase() === a.first.toLowerCase()), actual: `unchecked ${a.first}; groups now ${a.after.join(", ")}` }),
  },
];

